import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
import "core-js/modules/es.iterator.map.js";
import "core-js/modules/es.iterator.reduce.js";
import "core-js/modules/web.url-search-params.delete.js";
import "core-js/modules/web.url-search-params.has.js";
import "core-js/modules/web.url-search-params.size.js";
import * as echarts from "echarts";
export default {
  name: "DiagnosisView",
  data() {
    return {
      activeTab: "single",
      // 单图诊断数据
      leftEyeFile: null,
      rightEyeFile: null,
      leftEyeImage: null,
      rightEyeImage: null,
      // 批量诊断数据
      batchFileList: [],
      pairedImages: [],
      unpairedImages: [],
      // 处理状态
      processingMode: "single",
      // 'single' 或 'batch'
      processingDialogVisible: false,
      processingPercentage: 0,
      processedCount: 0,
      totalProcessCount: 0,
      taskQueue: [],
      currentTaskIndex: 0,
      // 结果数据
      showResults: false,
      singleResult: {
        leftEye: {
          diagnosis: "",
          confidence: 0,
          probabilities: []
        },
        rightEye: {
          diagnosis: "",
          confidence: 0,
          probabilities: []
        },
        finalDiagnosis: "",
        suggestion: ""
      },
      batchResults: [],
      // 历史记录
      historyRecords: [],
      // 疾病类别
      diseaseCategories: ["糖尿病视网膜病变", "青光眼", "白内障", "AMD", "高血压视网膜病变", "近视", "其他异常", "正常"]
    };
  },
  computed: {
    canProcess() {
      return this.leftEyeFile && this.rightEyeFile;
    }
  },
  methods: {
    // 标签页切换
    handleTabChange(tab) {
      this.showResults = false;
    },
    // 单图上传处理
    handleLeftEyeChange(file) {
      this.leftEyeFile = file.raw;
      this.leftEyeImage = URL.createObjectURL(file.raw);
    },
    handleRightEyeChange(file) {
      this.rightEyeFile = file.raw;
      this.rightEyeImage = URL.createObjectURL(file.raw);
    },
    removeLeftEye() {
      this.leftEyeFile = null;
      this.leftEyeImage = null;
    },
    removeRightEye() {
      this.rightEyeFile = null;
      this.rightEyeImage = null;
    },
    // 批量上传处理
    handleBatchChange(file, fileList) {
      this.batchFileList = fileList;
      this.analyzeBatchFiles();
    },
    handleBatchRemove(file, fileList) {
      this.batchFileList = fileList;
      this.analyzeBatchFiles();
    },
    clearBatchFiles() {
      this.batchFileList = [];
      this.pairedImages = [];
      this.unpairedImages = [];
    },
    analyzeBatchFiles() {
      // 分析文件名，配对左右眼图像
      const leftEyes = {};
      const rightEyes = {};
      const paired = [];
      const unpaired = [];

      // 正则表达式匹配ID和左右眼标识
      const regex = /(\d+)_(left|right)\.(jpg|jpeg|png)/i;
      this.batchFileList.forEach(file => {
        const match = file.name.match(regex);
        if (match) {
          const id = match[1];
          const side = match[2].toLowerCase();
          if (side === "left") {
            leftEyes[id] = file;
          } else if (side === "right") {
            rightEyes[id] = file;
          }
        } else {
          unpaired.push(file);
        }
      });

      // 配对左右眼
      for (const id in leftEyes) {
        if (rightEyes[id]) {
          paired.push({
            id,
            leftEye: leftEyes[id],
            rightEye: rightEyes[id]
          });

          // 从未配对列表中移除已配对的文件
          delete leftEyes[id];
          delete rightEyes[id];
        }
      }

      // 剩余未配对的文件
      for (const id in leftEyes) {
        unpaired.push(leftEyes[id]);
      }
      for (const id in rightEyes) {
        unpaired.push(rightEyes[id]);
      }
      this.pairedImages = paired;
      this.unpairedImages = unpaired;
    },
    // 文件上传前验证
    beforeUpload(file) {
      const isImage = file.type.startsWith("image/");
      const isLt5M = file.size / 1024 / 1024 < 5;
      if (!isImage) {
        this.$message.error("只能上传图片文件!");
        return false;
      }
      if (!isLt5M) {
        this.$message.error("图片大小不能超过 5MB!");
        return false;
      }
      return false; // 阻止自动上传
    },
    // 处理图像
    processSingleImages() {
      this.processingMode = "single";
      this.processingDialogVisible = true;
      this.processingPercentage = 0;

      // 模拟处理过程
      const timer = setInterval(() => {
        this.processingPercentage += 10;
        if (this.processingPercentage >= 100) {
          clearInterval(timer);
          setTimeout(() => {
            this.processingDialogVisible = false;
            this.generateSingleResult();
            this.showResults = true;
          }, 500);
        }
      }, 300);
    },
    processBatchImages() {
      this.processingMode = "batch";
      this.processingDialogVisible = true;
      this.processingPercentage = 0;
      this.processedCount = 0;
      this.totalProcessCount = this.pairedImages.length;

      // 创建任务队列
      this.taskQueue = this.pairedImages.map((pair, index) => ({
        id: pair.id,
        status: index === 0 ? "processing" : "waiting"
      }));
      this.currentTaskIndex = 0;

      // 模拟批量处理过程
      this.processBatchTask();
    },
    processBatchTask() {
      if (this.currentTaskIndex >= this.taskQueue.length) {
        // 所有任务处理完成
        setTimeout(() => {
          this.processingDialogVisible = false;
          this.generateBatchResults();
          this.showResults = true;
        }, 500);
        return;
      }
      const task = this.taskQueue[this.currentTaskIndex];
      task.status = "processing";

      // 模拟单个任务处理过程
      let progress = 0;
      const timer = setInterval(() => {
        progress += 20;
        this.processingPercentage = Math.floor((this.processedCount * 100 + progress) / this.totalProcessCount);
        if (progress >= 100) {
          clearInterval(timer);
          task.status = "completed";
          this.processedCount++;
          this.currentTaskIndex++;
          if (this.currentTaskIndex < this.taskQueue.length) {
            this.processBatchTask();
          } else {
            this.processingPercentage = 100;
            setTimeout(() => {
              this.processingDialogVisible = false;
              this.generateBatchResults();
              this.showResults = true;
            }, 500);
          }
        }
      }, 200);
    },
    getTaskStatusText(status) {
      switch (status) {
        case "waiting":
          return "等待中";
        case "processing":
          return "处理中";
        case "completed":
          return "已完成";
        default:
          return "未知状态";
      }
    },
    percentageFormat(percentage) {
      return percentage + "%";
    },
    // 生成结果
    generateSingleResult() {
      // 模拟生成诊断结果
      const leftEyeProbs = this.generateRandomProbabilities();
      const rightEyeProbs = this.generateRandomProbabilities();
      const leftMaxIndex = this.getMaxProbabilityIndex(leftEyeProbs);
      const rightMaxIndex = this.getMaxProbabilityIndex(rightEyeProbs);
      this.singleResult = {
        leftEye: {
          diagnosis: this.diseaseCategories[leftMaxIndex],
          confidence: Math.round(leftEyeProbs[leftMaxIndex] * 100),
          probabilities: leftEyeProbs
        },
        rightEye: {
          diagnosis: this.diseaseCategories[rightMaxIndex],
          confidence: Math.round(rightEyeProbs[rightMaxIndex] * 100),
          probabilities: rightEyeProbs
        },
        finalDiagnosis: this.generateFinalDiagnosis(leftMaxIndex, rightMaxIndex),
        suggestion: this.generateSuggestion(leftMaxIndex, rightMaxIndex)
      };

      // 添加到历史记录
      this.addToHistory(this.singleResult);

      // 渲染图表
      this.$nextTick(() => {
        this.renderEyeChart("leftEyeChart", this.singleResult.leftEye.probabilities);
        this.renderEyeChart("rightEyeChart", this.singleResult.rightEye.probabilities);
      });
    },
    generateBatchResults() {
      // 模拟生成批量诊断结果
      this.batchResults = this.pairedImages.map(pair => {
        const leftEyeProbs = this.generateRandomProbabilities();
        const rightEyeProbs = this.generateRandomProbabilities();
        const leftMaxIndex = this.getMaxProbabilityIndex(leftEyeProbs);
        const rightMaxIndex = this.getMaxProbabilityIndex(rightEyeProbs);
        const result = {
          id: pair.id,
          leftEye: {
            diagnosis: this.diseaseCategories[leftMaxIndex],
            confidence: Math.round(leftEyeProbs[leftMaxIndex] * 100),
            probabilities: leftEyeProbs
          },
          rightEye: {
            diagnosis: this.diseaseCategories[rightMaxIndex],
            confidence: Math.round(rightEyeProbs[rightMaxIndex] * 100),
            probabilities: rightEyeProbs
          },
          finalDiagnosis: this.generateFinalDiagnosis(leftMaxIndex, rightMaxIndex),
          suggestion: this.generateSuggestion(leftMaxIndex, rightMaxIndex)
        };

        // 添加到历史记录
        this.addToHistory(result);
        return result;
      });
    },
    generateRandomProbabilities() {
      // 生成随机概率分布
      const probs = Array(this.diseaseCategories.length).fill(0).map(() => Math.random());
      const sum = probs.reduce((a, b) => a + b, 0);
      return probs.map(p => p / sum);
    },
    getMaxProbabilityIndex(probabilities) {
      return probabilities.indexOf(Math.max(...probabilities));
    },
    generateFinalDiagnosis(leftIndex, rightIndex) {
      // 根据左右眼结果生成综合诊断
      if (leftIndex === rightIndex) {
        return `双眼${this.diseaseCategories[leftIndex]}`;
      } else if (leftIndex === 7 || rightIndex === 7) {
        // 7是"正常"的索引
        const abnormalIndex = leftIndex === 7 ? rightIndex : leftIndex;
        const abnormalSide = leftIndex === 7 ? "右眼" : "左眼";
        return `${abnormalSide}${this.diseaseCategories[abnormalIndex]}，另眼正常`;
      } else {
        return `左眼${this.diseaseCategories[leftIndex]}，右眼${this.diseaseCategories[rightIndex]}`;
      }
    },
    generateSuggestion(leftIndex, rightIndex) {
      // 根据诊断结果生成建议
      const suggestions = {
        0: "建议进行血糖控制，定期复查眼底，必要时考虑激光或抗VEGF治疗。",
        1: "建议测量眼压，进行视野检查，必要时使用降眼压药物。",
        2: "建议进行视力矫正，必要时考虑白内障手术。",
        3: "建议定期监测黄斑区变化，必要时考虑抗VEGF治疗。",
        4: "建议控制血压，定期复查眼底。",
        5: "建议进行屈光矫正，控制近距离用眼时间。",
        6: "建议进一步检查确定具体异常类型。",
        7: "眼底未见明显异常，建议定期检查。"
      };
      if (leftIndex === rightIndex) {
        return suggestions[leftIndex];
      } else {
        return `左眼：${suggestions[leftIndex]}\n右眼：${suggestions[rightIndex]}`;
      }
    },
    renderEyeChart(chartId, probabilities) {
      const chartDom = this.$refs[chartId];
      const myChart = echarts.init(chartDom);
      const option = {
        tooltip: {
          trigger: "axis",
          axisPointer: {
            type: "shadow"
          },
          formatter: params => {
            const dataIndex = params[0].dataIndex;
            const value = params[0].value;
            return `${this.diseaseCategories[dataIndex]}: ${(value * 100).toFixed(2)}%`;
          }
        },
        grid: {
          left: "3%",
          right: "4%",
          bottom: "3%",
          containLabel: true
        },
        xAxis: {
          type: "category",
          data: this.diseaseCategories.map(cat => cat.substring(0, 4) + "..."),
          axisLabel: {
            interval: 0,
            rotate: 45
          }
        },
        yAxis: {
          type: "value",
          axisLabel: {
            formatter: "{value}%"
          },
          max: 100
        },
        series: [{
          name: "概率",
          type: "bar",
          data: probabilities.map(p => (p * 100).toFixed(2)),
          itemStyle: {
            color: function (params) {
              const colorList = ["#c23531", "#2f4554", "#61a0a8", "#d48265", "#91c7ae", "#749f83", "#ca8622", "#bda29a"];
              return colorList[params.dataIndex];
            }
          }
        }]
      };
      myChart.setOption(option);

      // 响应窗口大小变化
      window.addEventListener("resize", function () {
        myChart.resize();
      });
    },
    // 报告操作
    saveReport() {
      this.$message.success("报告已保存到系统");
    },
    exportReport() {
      this.$message.success("报告已导出为PDF文件");
    },
    viewBatchDetail(row) {
      // 查看批量诊断中的单个详情
      this.$router.push(`/reports/detail/${row.id}`);
    },
    exportBatchReport(row) {
      this.$message.success(`ID ${row.id} 的报告已导出为PDF文件`);
    },
    saveAllBatchReports() {
      this.$message.success(`已保存全部 ${this.batchResults.length} 份报告`);
    },
    exportAllBatchReports() {
      this.$message.success(`已导出全部 ${this.batchResults.length} 份报告为PDF文件`);
    },
    // 历史记录操作
    addToHistory(result) {
      const now = new Date();
      const timeStr = now.toLocaleString();
      this.historyRecords.unshift({
        ...result,
        time: timeStr
      });
    },
    viewHistoryDetail(row) {
      this.$router.push(`/reports/detail/${row.id}`);
    },
    exportHistoryReport(row) {
      this.$message.success(`历史记录 ID ${row.id} 的报告已导出为PDF文件`);
    }
  },
  mounted() {
    // 检查登录状态
    const isLoggedIn = localStorage.getItem("isLoggedIn");
    if (!isLoggedIn) {
      this.$router.push("/login");
    }

    // 初始化一些模拟历史记录
    for (let i = 0; i < 5; i++) {
      const leftEyeProbs = this.generateRandomProbabilities();
      const rightEyeProbs = this.generateRandomProbabilities();
      const leftMaxIndex = this.getMaxProbabilityIndex(leftEyeProbs);
      const rightMaxIndex = this.getMaxProbabilityIndex(rightEyeProbs);
      const date = new Date();
      date.setDate(date.getDate() - i);
      this.historyRecords.push({
        id: `PT2023${100 + i}`,
        time: date.toLocaleString(),
        leftEye: {
          diagnosis: this.diseaseCategories[leftMaxIndex],
          confidence: Math.round(leftEyeProbs[leftMaxIndex] * 100),
          probabilities: leftEyeProbs
        },
        rightEye: {
          diagnosis: this.diseaseCategories[rightMaxIndex],
          confidence: Math.round(rightEyeProbs[rightMaxIndex] * 100),
          probabilities: rightEyeProbs
        },
        finalDiagnosis: this.generateFinalDiagnosis(leftMaxIndex, rightMaxIndex)
      });
    }
  }
};
